/* Comic Reader — extracted from index.html v3. Classic script; keep execution order. */

/* ===== original script 8: nxComicReaderEmbeddedApp ===== */
(function(){
  'use strict';

  var COMIC_READER_APP_B64 = '';
  var activeComicFrame = null;

  function decodeComicApp(value){
    var binary = atob(value);
    var bytes = new Uint8Array(binary.length);
    for(var i=0;i<binary.length;i++) bytes[i]=binary.charCodeAt(i);
    if(typeof TextDecoder!=='undefined') return patchComicApp(new TextDecoder('utf-8').decode(bytes));
    var encoded='';
    for(var j=0;j<bytes.length;j++) encoded += '%' + bytes[j].toString(16).padStart(2,'0');
    return patchComicApp(decodeURIComponent(encoded));
  }

  function patchComicApp(html){
    return String(html)
      .replace("const SOURCE_API = 'https://www.alltoolsniel.my.id/api/mangadex';", "const SOURCE_API = '/api/comics';")
      .replace("const SOURCE_IMAGE_PROXY = 'https://www.alltoolsniel.my.id/api/mangadex?action=image-proxy&url=';", "const SOURCE_IMAGE_PROXY = '';")
      .replace("function sourceImageUrl(raw){\n  return raw ? SOURCE_IMAGE_PROXY+encodeURIComponent(raw) : '';\n}", "function sourceImageUrl(raw){ return raw || ''; }")
      .replace("const params=new URLSearchParams({action:'pages',id:chapter.id});", "const params=new URLSearchParams({action:'pages',id:chapter.id,quality:state.readerQuality});")
      .replace("state.sourceMode='source';\n  return json;", "state.sourceMode='source';\n  const statusBadge=document.getElementById('nxComicApiHealth');if(statusBadge){statusBadge.className='ok';statusBadge.innerHTML='<i></i><span>Nexora Comic API aktif</span>';}\n  return json;")
      .replace(/All Tools Nexora \/\/ Comic Core/g, 'Nexora // Comic Reader')
      .replace(/<button class="tab" data-tab="xyz"[^>]*><i class="fa-solid fa-bolt"><\/i> xyZ Manga<\/button>/, '<button class="tab" data-tab="xyz" type="button"><i class="fa-solid fa-compass"></i> Pilihan</button>')
      .replace('<main class="workspace">', '<main class="workspace"><div class="manga-attribution"><i class="fa-solid fa-circle-info"></i><span>Data dan halaman dari <a href="https://mangadex.org" target="_blank" rel="noopener noreferrer">MangaDex</a>. Hak karya milik kreator; chapter dikreditkan kepada grup scanlation terkait.</span></div>')
      .replace('<div id="mangaTabs" class="tabs">', '<div id="mangaTabs" class="tabs" data-label="Sort">')
      .replace('<div id="mangaCategoryTabs" class="tabs">', '<div id="mangaCategoryTabs" class="tabs" data-label="Type">')
      .replace('<div id="mangaStatusTabs" class="tabs">', '<div id="mangaStatusTabs" class="tabs" data-label="Status">')
      .replace('<input type="text" id="mangaSearchInput" placeholder="Cari manga, manhwa, atau manhua">', '<input type="search" id="mangaSearchInput" placeholder="Cari manga, manhwa, atau manhua" aria-label="Cari komik" autocomplete="off" enterkeyhint="search">')
      .replace('<button id="mangaSearchBtn" type="button">', '<button id="mangaSearchBtn" type="button" aria-label="Cari komik">')
      .replace('</head>', '<link rel="stylesheet" href="/assets/css/features/comic-reader-mobile.css?v=20260831"><style>.manga-attribution{display:flex;align-items:flex-start;gap:8px;margin:0 0 10px;padding:9px 11px;border:1px solid rgba(192,132,252,.18);border-radius:12px;background:rgba(168,85,247,.06);color:#a995c5;font-size:9px;font-weight:700;line-height:1.55}.manga-attribution i,.manga-attribution a{color:#c084fc}.manga-attribution a{text-decoration:none}</style></head>')
      .replace('return `<img src="${sourceImageUrl(rawUrl)}" loading="lazy" alt="cover" data-raw="${raw}" data-fallback-stage="0" onerror="mangaCoverFallback(this)">`;', 'return `<img src="${sourceImageUrl(rawUrl)}" loading="lazy" decoding="async" alt="cover" data-raw="${raw}" data-fallback-stage="0" onerror="mangaCoverFallback(this)">`;')
      .replace('function mangaDoSearch(){', "function mangaResetFilters(){\n  state.tab='latest';state.category='all';state.statusFilter='all';state.query='';\n  $('mangaSearchInput').value='';\n  document.querySelectorAll('#mangaTabs .tab').forEach(b=>b.classList.toggle('active',b.dataset.tab==='latest'));\n  document.querySelectorAll('#mangaCategoryTabs .tab').forEach(b=>b.classList.toggle('active',b.dataset.category==='all'));\n  document.querySelectorAll('#mangaStatusTabs .tab').forEach(b=>b.classList.toggle('active',b.dataset.status==='all'));\n  mangaShowHome(true);\n}\nfunction mangaDoSearch(){")
      .replace('<div class="empty"><i class="fa-solid fa-magnifying-glass"></i><span>Komik tidak ditemukan.</span></div>', '<div class="empty"><i class="fa-solid fa-magnifying-glass"></i><span><strong>Komik tidak ditemukan.</strong><small>Coba kata kunci atau filter lain.</small></span><button class="nav-btn" onclick="mangaResetFilters()"><i class="fa-solid fa-filter-circle-xmark"></i> Reset Filter</button></div>')
      .replace("<span>Gagal memuat data komik.<br><small>${escapeHtml(error.message||'Koneksi bermasalah')}</small></span>", '<span><strong>Tidak dapat memuat daftar komik.</strong><small>Coba lagi beberapa saat.</small></span>')
      .replace("<span>Gagal memuat detail komik.<br><small>${escapeHtml(error.message||'Koneksi bermasalah')}</small></span>", '<span><strong>Tidak dapat memuat detail komik.</strong><small>Coba lagi beberapa saat.</small></span>')
      .replace("<span>Gagal memuat daftar chapter.<br><small>${escapeHtml(error.message||'')}</small></span>", '<span><strong>Tidak dapat memuat daftar chapter.</strong><small>Coba lagi beberapa saat.</small></span>')
      .replace("<span>Gagal memuat gambar chapter.<br><small>${escapeHtml(error.message||'')}</small></span>", '<span><strong>Tidak dapat memuat gambar chapter.</strong><small>Coba lagi beberapa saat.</small></span>')
      .replace('loading="${pageIndex<2?\'eager\':\'lazy\'}" alt="Halaman ${pageIndex+1}"', 'loading="${pageIndex<2?\'eager\':\'lazy\'}" decoding="async" alt="Halaman ${pageIndex+1}"')
      .replace('function tracked(url){\n    try{', "function tracked(url){\n    if(String(url||'').indexOf('/api/comics')===0) return true;\n    try{")
      .replace('return host === "api.mangadex.org" ||\n        host === "uploads.mangadex.org";', 'return host === location.hostname || host === "api.mangadex.org" ||\n        host === "uploads.mangadex.org";');
  }

  function closeComicReader(event){
    if(event){
      event.preventDefault();
      event.stopPropagation();
      if(typeof event.stopImmediatePropagation==='function') event.stopImmediatePropagation();
    }

    var room=document.getElementById('nxUniversalRoom');
    if(!room || room.getAttribute('data-tool')!=='comicreader') return false;

    room.classList.remove('is-visible','is-open');
    room.style.display='none';
    room.setAttribute('aria-hidden','true');

    var body=document.getElementById('nxUniversalRoomBody');
    if(body) body.innerHTML='';

    document.body.classList.remove('nx-universal-room-open');
    document.body.style.overflow='auto';
    activeComicFrame=null;

    if(history.state && history.state.nxUniversalTool==='comicreader'){
      try{ history.back(); }catch(ignore){}
    }else if(location.hash.indexOf('#tool-comicreader')===0){
      try{ history.replaceState(null,'',location.href.split('#')[0]); }catch(ignore){}
    }
    return true;
  }

  window.renderComicReader=function(body){
    body.innerHTML=
      '<div class="nx-comic-embed">'+
        '<div class="nx-comic-loading" id="nxComicLoading">Loading Comic Core</div>'+
        '<iframe class="nx-comic-frame" id="nxComicFrame" title="All Tools Nexora Baca Komik Full" sandbox="allow-scripts allow-forms allow-popups allow-modals allow-downloads allow-same-origin" allow="clipboard-write" referrerpolicy="no-referrer" loading="eager"></iframe>'+
      '</div>';

    var frame=document.getElementById('nxComicFrame');
    var loading=document.getElementById('nxComicLoading');
    activeComicFrame=frame;
    if(!frame) return;

    frame.addEventListener('load',function(){
      if(loading) loading.classList.add('is-hidden');
    },{once:true});

    try{
      frame.srcdoc=decodeComicApp(COMIC_READER_APP_B64);
    }catch(error){
      if(loading){
        loading.textContent='Comic Core gagal dimuat';
        loading.style.color='#fb7185';
      }
      console.error('[Baca Komik Full]',error);
    }
  };

  window.addEventListener('message',function(event){
    if(!activeComicFrame || event.source!==activeComicFrame.contentWindow || !event.data) return;
    if(event.data.type==='nx-close-comic-reader') closeComicReader();
  });

  document.addEventListener('click',function(event){
    var button=event.target&&event.target.closest?event.target.closest('#nxUniversalRoomBack'):null;
    var room=document.getElementById('nxUniversalRoom');
    if(button&&room&&room.classList.contains('is-open')&&room.getAttribute('data-tool')==='comicreader'){
      closeComicReader(event);
    }
  },true);

  document.addEventListener('keydown',function(event){
    var room=document.getElementById('nxUniversalRoom');
    if(event.key==='Escape'&&room&&room.classList.contains('is-open')&&room.getAttribute('data-tool')==='comicreader'){
      closeComicReader(event);
    }
  },true);

  window.closeComicReaderNexora=closeComicReader;
})();
